Definition VSCR : Z := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2'D!1,A|:000;!2'a5'a6'a7").

Theorem visit_end_array_deep_ok : forall (LBo : list (Z * Z)) (cr : credit) (sp r V S2 kx bx : Z) (g : eghost) (c0 c2 : ectx) (r0 : estate),
  g_es g = c0 :: c2 :: r0 ->
  PML.cps_heap L HI PC_VISIT_END_ARRAY r sp VSCR (LBo ++ g_lbv g) cr
    (fun R M => PML.entry L R M sp r VSCR /\ PML.a0 R V /\ True /\ enc_inv M V S2 g /\ ev_guard (g_es g) EvEnd /\ eroomU g EvEnd /\ PML.img_ro M /\ PML.lits_ok M /\
                ecreditU L cr g kx bx /\ objs_enc L sp V S2)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
        PML.a0 R' 1 /\ enc_inv M' V S2 g' /\ g_es g' = estep (g_es g) EvEnd /\ pay_ok EvEnd pay /\ g_len g' = g_len g + ev_ind (g_es g) EvEnd + pay /\
        PML.lits_ok M' /\ LB' = LBo ++ g_lbv g' /\ LBk = LBo /\ W = W_enc V S2 /\ ecreditU L cr' g' kx bx).
Proof using APPEND_OK FPM HIok LAY NEWLINE2_OK.
  intros LBo cr sp r V S2 kx bx g c0 c2 r0 Hes. unfold PML.cps_heap.
  intros fx R M model K HH Hmo HKnil Hfp (Hentry & Ha0 & _ & Hinv & _ & Hroom & Himg & Hlits & Hcred & Hobjs) Hcont.
  destruct Hentry as (Hra & Hraok & Hsp & Htp & Hstk). destruct Hstk as (S1 & S2' & S3 & S4 & S5).
  assert (VS : VSCR = EVEB.SCRW) by reflexivity. rewrite VS in S2', S5. unfold EVEB.SCRW in S2'.
  pose proof Hobjs as ((OV1 & OV2 & OV3) & (OS1 & OS2 & OS3) & OAP). unfold ENC_SIZE, PML.apart in OV2, OAP.
  pose proof (PmLayout.ly_segs L LAY) as LS. pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
  pose proof (PmLayout.ly_errno L LAY) as LER. pose proof (PmLayout.ly_kpm L LAY) as KPM. pose proof (PmLayout.ly_bov L LAY) as BOV.
  destruct g as [es0 len0 rep b cb]. cbn [g_es g_len g_rep g_sb g_scap] in *. subst es0.
  destruct c0 as [arr cnt nla0]. destruct c2 as [arr2 cnt2 nla2].
  set (d2 := depth r0).
  assert (DR0 : 0 <= d2) by (unfold d2, depth; lia).
  assert (DES : depth (ECtx arr cnt nla0 :: ECtx arr2 cnt2 nla2 :: r0) = d2 + 2) by (unfold d2, depth; cbn [length]; lia).
  assert (DES1 : depth (ECtx arr2 cnt2 nla2 :: r0) = d2 + 1) by (unfold d2, depth; cbn [length]; lia).
  assert (EVI : ev_ind (ECtx arr cnt nla0 :: ECtx arr2 cnt2 nla2 :: r0) EvEnd = (if nla0 then 1 + 4 * (d2 + 1) else 0) + 1).
  { unfold ev_ind. cbn [ec_nla]. rewrite DES1. reflexivity. }
  assert (HRM : len0 + 1 <= CLU /\ (nla0 = true -> len0 + (1 + 4 * (d2 + 1)) + 1 <= CLU)).
  { unfold eroomU, kmax, pay_hi in Hroom. cbn [g_len g_es] in Hroom. rewrite EVI in Hroom.
    split; [destruct nla0; cbv iota in Hroom; lia | intros ->; cbv iota in Hroom; lia]. }
  pose proof Hinv as (I1 & I2 & I3 & I4 & I5). cbn [g_es g_len g_rep g_sb g_scap] in I1, I2, I3, I4, I5.
  rewrite DES in I1, I5. unfold MAX_DEPTH in I5.
  pose proof I2 as TT. unfold stack_at in TT. destruct TT as (T1 & T2 & T3 & T4 & T5 & T6). rewrite DES in T2, T4.
  assert (P10 : 2 ^ 10 = 1024) by reflexivity.
  assert (CB : 32 <= cb <= 32768).
  { destruct T5 as [(E1 & E2)|(k0 & Hk0 & Ecb)]; [lia|]. rewrite Ecb.
    pose proof (Z.pow_pos_nonneg 2 k0 ltac:(lia) (proj1 Hk0)) as Q1. pose proof (Z.pow_le_mono_r 2 k0 10 ltac:(lia) (proj2 Hk0)) as Q2. lia. }
  set (es := ECtx arr cnt nla0 :: ECtx arr2 cnt2 nla2 :: r0) in *.
  set (esp := ECtx arr2 cnt2 nla2 :: r0) in *.
  assert (LBV : g_lbv (EG es len0 rep b cb) = PML.srep_blocks rep ++ [(b, cb)]).
  { unfold g_lbv, stack_blocks. cbn [g_rep g_sb g_scap]. destruct (Z.eqb_spec cb 0); [lia | reflexivity]. }
  assert (HH' : hi_heap HI (LBo ++ PML.srep_blocks rep ++ [(b, cb)]) cr M (m_vmmaps model)) by (rewrite <- LBV; exact HH).
  clear HH. rename HH' into HH.
  destruct (hio_wf L SCFG HI HIok _ _ _ _ HH) as (Hwf & Hnd & Hcr0).
  assert (INB : In (b, cb) (LBo ++ PML.srep_blocks rep ++ [(b, cb)])) by (apply in_or_app; right; apply in_or_app; right; left; reflexivity).
  destruct (Hwf _ INB) as ((B0 & B1 & B2 & B3 & B4) & _ & _). cbn [fst snd] in B0, B1, B2, B3, B4.
  assert (HHp : hi_heap HI ((b, cb) :: LBo ++ PML.srep_blocks rep) cr M (m_vmmaps model)).
  { apply (CH2V.hi_heap_perm L HI HIok _ _ _ _ _ HH). rewrite app_assoc. apply Permutation_sym, Permutation_cons_append. }
  assert (HC : ctx_at M (b + 32 * (d2 + 1)) (ECtx arr cnt nla0)).
  { pose proof (EK3.stack_head M V (ECtx arr cnt nla0) esp b cb I2) as X. rewrite DES1 in X. exact X. }
  assert (HD : ctx_at M (b + 32 * d2) (ECtx arr2 cnt2 nla2)) by exact (EK3.stack_second M V (ECtx arr cnt nla0) (ECtx arr2 cnt2 nla2) r0 b cb I2).
  pose proof HC as (HQ1 & HQ2 & HQ3 & HQ4 & HQ5 & HQ6). cbn [ec_arr ec_count ec_nla] in HQ1, HQ2, HQ3, HQ4, HQ5, HQ6.
  pose proof HD as (HR1 & HR2 & HR3 & HR4 & HR5 & HR6). cbn [ec_arr ec_count ec_nla] in HR1, HR2, HR3, HR4, HR5, HR6.
  assert (BRR : 4096 <= b /\ 0 <= d2 <= 1022 /\ b + 32 * (d2 + 2) <= hl_ceil L) by lia.
  assert (BIMG0 : b + 32 * (d2 + 2) <= hl_img_lo L \/ hl_img_hi L <= b) by lia.
  pose proof BIMG0 as BIMG. rewrite ILO, IHI in BIMG.
  destruct (EAK.bytes_of_defined M 1 (b + 32 * (d2 + 1) + 5) ltac:(lia) ltac:(unfold hl_ceil in B4; lia)) as (ibs & Hibl & Hib).
  { intros j Hj. replace (b + 32 * (d2 + 1) + 5 + j) with (b + 32 * (d2 + 1) + (5 + j)) by lia. apply HQ6. lia. }
  destruct ibs as [|ib [|ib2 ibs]]; cbn [length] in Hibl; try discriminate. clear Hibl.
  pose proof (Hib 0%nat ltac:(cbn [length]; lia)) as Hib0. cbn [nth] in Hib0. change (Z.of_nat 0) with 0 in Hib0. rewrite Z.add_0_r in Hib0.
  assert (IB : 0 <= ib mod 256 < 256) by (apply Z.mod_pos_bound; lia).
